import{_ as a,o as r,c as l,a6 as e}from"./chunks/framework.C1YrMf1e.js";const o="/Art_web_public/assets/image.DLQKGIjq.png",u=JSON.parse('{"title":"CSP中网点概念及用法","description":"","frontmatter":{"readingTime":"2 min read"},"headers":[],"relativePath":"全流程美术/漫画/CSP中网点概念及用法/CSP中网点概念及用法.md","filePath":"全流程美术/漫画/CSP中网点概念及用法/CSP中网点概念及用法.md"}'),i={name:"全流程美术/漫画/CSP中网点概念及用法/CSP中网点概念及用法.md"};function n(s,t,g,_,c,d){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="csp中网点概念及用法" tabindex="-1">CSP中网点概念及用法 <a class="header-anchor" href="#csp中网点概念及用法" aria-label="Permalink to &quot;CSP中网点概念及用法&quot;">​</a></h1><h2 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h2><h3 id="「x-0線」是什么意思" tabindex="-1">「X.0線」是什么意思？ <a class="header-anchor" href="#「x-0線」是什么意思" aria-label="Permalink to &quot;「X.0線」是什么意思？&quot;">​</a></h3><p><img src="'+o+'" alt="alt text"></p><ul><li><strong>「線」= 线数（line count）</strong>，也叫<strong>网线数</strong>，单位是 <strong>lpi（lines per inch）</strong>，表示每英寸长度内的网点行数。</li><li>数值越大，网点越<strong>细密</strong>，画面看起来更平滑、灰度更细腻；</li><li>数值越小，网点越<strong>粗疏</strong>，对比更强烈，颗粒感更明显。 <ul><li>比如：<strong>15.0線</strong> = 非常粗的网点，适合做大面积暗部或强烈质感；</li><li><strong>65.0線</strong> = 很细密的网点，适合做渐变、柔和过渡或精细的阴影。</li></ul></li></ul><h3 id="「5-10-50-」是什么意思" tabindex="-1">「5% / 10% / 50%」是什么意思？ <a class="header-anchor" href="#「5-10-50-」是什么意思" aria-label="Permalink to &quot;「5% / 10% / 50%」是什么意思？&quot;">​</a></h3><ul><li>这是<strong>网点覆盖率（dot percentage）</strong>，表示单位面积里黑色网点占比多少。</li><li>数值越大，整体色调越<strong>深</strong>；数值越小，色调越<strong>浅</strong>。 <ul><li>5%：极浅灰，几乎接近白纸，适合极淡的渐变或高光；</li><li>50%：中灰，是最常用的基础灰度；</li><li>60%：偏深灰，适合较重的阴影。</li></ul></li></ul><h3 id="「圓-線-雜訊」是什么意思" tabindex="-1">「圓 / 線 / 雜訊」是什么意思？ <a class="header-anchor" href="#「圓-線-雜訊」是什么意思" aria-label="Permalink to &quot;「圓 / 線 / 雜訊」是什么意思？&quot;">​</a></h3><p>这是网点的<strong>形状/类型</strong>：</p><ul><li><strong>圓（円）</strong>：圆形网点，最常见，过渡柔和；</li><li><strong>線</strong>：直线/条纹网点，适合表现木纹、布料或速度线；</li><li><strong>雜訊（雜訊）</strong>：杂色/颗粒网点，类似噪点，适合做粗糙质感、氛围或复古效果。</li></ul>',10)])])}const p=a(i,[["render",n]]);export{u as __pageData,p as default};
